"""Run through Blender MCP execute_blender_code. Deterministic, original assets.
Keeps the starting scene, builds in a dedicated scene, exports Godot GLBs.
"""
import bpy, math
from pathlib import Path
from mathutils import Vector
BASE = Path('/home/clau/dev/space-ranger')
OUT = BASE / 'assets/models/eclipse_expansion'
OUT.mkdir(parents=True, exist_ok=True)
scene = bpy.data.scenes.get('Eclipse Expansion Atelier') or bpy.data.scenes.new('Eclipse Expansion Atelier')
bpy.context.window.scene = scene
# Rebuild only the atelier generated by this tool; leave the starting scene intact.
if scene.name == 'Eclipse Expansion Atelier':
    for o in list(scene.objects): bpy.data.objects.remove(o, do_unlink=True)

def mat(name, color, metal=0.7, rough=0.32, glow=0):
    m=bpy.data.materials.new(name); m.diffuse_color=(*color,1); m.use_nodes=True
    p=m.node_tree.nodes.get('Principled BSDF'); p.inputs['Base Color'].default_value=(*color,1)
    p.inputs['Metallic'].default_value=metal; p.inputs['Roughness'].default_value=rough
    if glow:
        p.inputs['Emission Color'].default_value=(*color,1); p.inputs['Emission Strength'].default_value=glow
    return m
DARK=mat('Eclipse | carbon ceramic',(0.025,0.045,0.065),.65,.4)
STEEL=mat('Eclipse | brushed titanium',(.28,.39,.46),.88,.26)
WHITE=mat('Eclipse | pearl armor',(.72,.83,.86),.45,.34)
GOLD=mat('Eclipse | rescue amber',(.95,.48,.09),.7,.3)
CYAN=mat('Eclipse | ion cyan',(.035,.8,1),.25,.24,3)
MINT=mat('Eclipse | cryo mint',(.08,1,.65),.25,.24,3)
PINK=mat('Eclipse | void orchid',(.7,.15,1),.3,.24,3)
RED=mat('Eclipse | hostile optics',(1,.08,.025),.25,.24,3)

def empty(name,pos=(0,0,0),parent=None):
    o=bpy.data.objects.new(name,None); scene.collection.objects.link(o); o.parent=parent; o.location=pos; return o

def finish(o,name,pos,size,material,parent=None):
    o.name=name; o.location=pos; o.scale=size
    bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)
    o.data.materials.append(material)
    if o.type=='MESH':
        b=o.modifiers.new('Machined edge highlights','BEVEL'); b.width=.035; b.segments=2
        bpy.context.view_layer.objects.active=o; bpy.ops.object.modifier_apply(modifier=b.name)
        for poly in o.data.polygons: poly.use_smooth=True
        n=o.modifiers.new('Weighted plate normals','WEIGHTED_NORMAL')
        bpy.ops.object.modifier_apply(modifier=n.name)
    o.parent=parent
    return o

def box(name,pos,size,material,parent=None,rot=None):
    bpy.ops.mesh.primitive_cube_add(size=1)
    o=finish(bpy.context.object,name,pos,size,material,parent)
    if rot:o.rotation_euler=rot
    return o

def sphere(name,pos,size,material,parent=None):
    bpy.ops.mesh.primitive_uv_sphere_add(segments=20,ring_count=12,radius=1)
    return finish(bpy.context.object,name,pos,size,material,parent)

def rod(name,a,b,r,material,parent=None):
    a,b=Vector(a),Vector(b); d=b-a
    bpy.ops.mesh.primitive_cylinder_add(vertices=16,radius=r,depth=d.length)
    o=finish(bpy.context.object,name,(a+b)/2,(1,1,1),material,parent)
    o.rotation_euler=d.to_track_quat('Z','Y').to_euler();return o

def ring(name,pos,radius,width,material,parent=None):
    bpy.ops.mesh.primitive_torus_add(major_segments=40,minor_segments=8,major_radius=radius,minor_radius=width)
    o=finish(bpy.context.object,name,pos,(1,1,1),material,parent)
    o.rotation_euler.x=math.pi/2;return o

def export(name,objects):
    bpy.context.view_layer.update()
    bpy.ops.object.select_all(action='DESELECT')
    for o in objects:
        if o.name in bpy.context.view_layer.objects: o.select_set(True)
    bpy.ops.export_scene.gltf(filepath=str(OUT/(name+'.glb')),export_format='GLB',use_selection=True,export_animations=True,export_animation_mode='NLA_TRACKS')
    print('EXPORTED',name,len(objects))

def descendants(root): return [root]+list(root.children_recursive)

def cleanup(objects):
    for o in objects:bpy.data.objects.remove(o,do_unlink=True)

def tint_material(m,color):
    m=m.copy();m.name='Eclipse restyle | '+m.name
    if not m.use_nodes:return m
    p=m.node_tree.nodes.get('Principled BSDF')
    if not p:return m
    p.inputs['Metallic'].default_value=.65;p.inputs['Roughness'].default_value=.32
    inp=p.inputs['Base Color']
    if inp.is_linked:
        old=inp.links[0].from_socket
        mix=m.node_tree.nodes.new('ShaderNodeMixRGB');mix.blend_type='MULTIPLY';mix.inputs[0].default_value=.72
        mix.inputs[2].default_value=(*color,1)
        m.node_tree.links.new(old,mix.inputs[1]);m.node_tree.links.new(mix.outputs[0],inp)
    else:inp.default_value=(*color,1)
    return m

# Retain every skeleton, clip, socket and named articulation on existing models.
for source,name,accent in [('player','ranger',(.26,.72,.85)),('campaign_bosses/apex','apex',(.34,.47,.65)),('campaign_bosses/warden','warden',(.37,.24,.64)),('campaign_bosses/seraph','seraph',(.74,.33,.13))]:
    before=set(bpy.data.objects);bpy.ops.import_scene.gltf(filepath=str(BASE/'assets/models'/(source+'.glb')))
    objects=set(bpy.data.objects)-before
    mats={m for o in objects if o.type=='MESH' for m in o.data.materials if m}
    remap={}
    for m in mats:
        lower=m.name.lower()
        if any(w in lower for w in ['optic','visor','reactor','ruby','core','conduit']):
            c=(.03,.75,1) if name=='ranger' else ((.8,.12,1) if name=='warden' else (1,.38,.06))
            mm=mat('Eclipse '+name+' luminous '+m.name,c,.35,.22,2)
        elif any(w in lower for w in ['carbon','joint','seal','cavit','tendon','undersuit']):continue
        else:mm=tint_material(m,accent)
        remap[m]=mm
    for o in objects:
        if o.type=='MESH':
            for i,m in enumerate(o.data.materials):
                if m in remap:o.data.materials[i]=remap[m]
    # The ranger's existing sculpted suit supplies fitted armor; avoid box overlays.
    if name=='apex':
        parent=next((o for o in objects if o.name.startswith('ShoulderRocketPod_L')),None)
        if parent:
            for i in range(3):
                o=box('Amber rank insignia',(-.22+i*.07,-.22,.1),(.04,.025,.14),GOLD,parent);objects.add(o)
    elif name=='warden':
        parent=next(o for o in objects if o.name.startswith('ColossusTorso'))
        for i in range(5):
            o=box('Amethyst dorsal reactor',(0,.25+i*.23,.58),(.12,.18,.35-i*.025),PINK,parent,rot=(0,.3,0));objects.add(o)
    elif name=='seraph':
        parent=next(o for o in objects if o.name.startswith('SeraphHead'))
        for side in [-1,1]:
            o=box('Swept solar crown',(side*.33,0,.28),(.08,.16,.52),GOLD,parent,rot=(0,side*.45,0));objects.add(o)
    export(name,objects);cleanup(objects)

