    for i in range(4):
        box('Lance heatsink',(side*2.1,-.23,-.4-i*.18),(.3,.12,.075),DARK,root)
    for lateral in [-1,1]:
        box('Lance energy rail',(side*2.1+lateral*.17,0,-.85),(.055,.07,.8),MINT,root)
    empty('MuzzleLeft' if side<0 else 'MuzzleRight',(side*2.1,0,-1.38),root)
