# Eclipse Sovereign: floating multi-ring eye, radial segmented armor and cannons.
root=empty('Eclipse_Sovereign')
sphere('Singularity chamber',(0,0,0),(.9,.65,.9),DARK,root)
ring('Inner gilded aperture',(0,-.65,0),.65,.10,GOLD,root)
