    box('Radial crown armor',(x*1.68,0,z*1.68),(.46,.42,.65),STEEL,rotor,rot=(0,a,0))
    box('Orchid crown rune',(x*1.7,-.235,z*1.7),(.12,.025,.37),PINK,rotor,rot=(0,a,0))
