# Original scene props, reusable across the five biome palettes.
for name,glow in [('cryo_tower',MINT),('reactor_arch',CYAN),('void_obelisk',PINK)]:
    root=empty(name)
    if name=='reactor_arch':
        for side in [-1,1]:
            box('Portal pier',(side*3,0,3),(.65,.85,6),DARK,root)
            box('Pier ion inset',(side*3,-.45,3),(.09,.035,4.8),glow,root)
        box('Truss lintel',(0,0,6),(6.7,.85,.6),STEEL,root)
        for i in range(7):box('Amber chevron',(-2.4+i*.8,-.45,6),(.3,.04,.25),GOLD,root,rot=(0,.35,0))
    elif name=='cryo_tower':
        box('Cooling base',(0,0,.25),(1.9,1.9,.5),DARK,root)
        rod('Cryo reservoir',(0,0,.5),(0,0,4.5),.7,WHITE,root)
        for i in range(7):
            r=ring('Heat exchanger',(0,0,.8+i*.55),.84,.055,STEEL,root);r.rotation_euler.x=0
        for side in [-1,1]:box('Coolant inspection strip',(side*.4,-.59,2.5),(.1,.08,3.4),glow,root)
        sphere('Coolant cap',(0,0,4.65),(.63,.63,.25),glow,root)
    else:
        box('Plinth',(0,0,.2),(2,1.5,.4),DARK,root)
        box('Suspended monolith',(0,0,2.8),(1,.8,4.5),STEEL,root,rot=(0,.15,0))
        box('Void aperture',(0,-.44,2.8),(.16,.05,3.6),glow,root,rot=(0,.15,0))
        ring('Orbital seal',(0,-.5,3),1.3,.045,GOLD,root)
    export(name,descendants(root));cleanup(descendants(root))
# Save a source workbench containing all authored exports arranged in a gallery.
for i,name in enumerate(['ranger','apex','warden','seraph','hound','wasp','leviathan','sovereign','cryo_tower','reactor_arch','void_obelisk']):
    before=set(bpy.data.objects);bpy.ops.import_scene.gltf(filepath=str(OUT/(name+'.glb')))
    for o in set(bpy.data.objects)-before:
        if o.parent is None:o.location.x+=i*9
bpy.data.libraries.write(str(OUT/'eclipse_atelier.blend'), {scene}, fake_user=True, compress=True)
print('ECLIPSE EXPANSION COMPLETE')
